import json
h,w=17,30
out=[[0]*w for _ in range(h)]
# Preserve each object's complete 5x5 silhouette and original column position;
# align their top edges to the top edge of the 8-object (row 7).
shapes={
  3:{0:[2,3,4,5,6],1:[4],2:[3,4,5],3:[2,3,4,5,6],4:[4]},
  1:{0:[9,10,11,12,13],1:[11],2:[10,11,12],3:[9,10,11,12,13],4:[11]},
  4:{0:[14,15,16,17,18],1:[16],2:[15,16,17],3:[14,15,16,17,18],4:[16]},
  8:{0:[21,22,23,24,25],1:[23],2:[22,23,24],3:[21,22,23,24,25],4:[23]},
}
for color, rows in shapes.items():
    for dr, cols in rows.items():
        for c in cols:
            out[7+dr][c]=color
assert len(out)==17 and all(len(row)==30 for row in out)
print(json.dumps(out))
